// Mesmo helper exportado pelo banco de inglês — vários jogos importam
// `shuffleArray` junto com as palavras, então os dois cursos precisam oferecê-lo.
export const shuffleArray = (arr) => {
  const copia = [...arr];
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copia[i], copia[j]] = [copia[j], copia[i]];
  }
  return copia;
};

